```turtle
@prefix ea:   <http://example.org/onto/assessment#> .
@prefix owl:  <http://www.w3.org/2002/07/owl#> .
@prefix rdf:  <http://www.w3.org/1999/02/22-rdf-syntax-ns#> .
@prefix rdfs: <http://www.w3.org/2000/01/rdf-schema#> .
@prefix xsd:  <http://www.w3.org/2001/XMLSchema#> .
@prefix skos: <http://www.w3.org/2004/02/skos/core#> .

<http://example.org/onto/assessment>
  a owl:Ontology ;
  rdfs:label "Educational Assessment Ontology" .

#################################################################
# TOP CLASS
#################################################################

ea:Assessment a owl:Class ;
  rdfs:label "Assessment" ;
  skos:altLabel "educational evaluation" ;
  rdfs:comment "The systematic process of documenting and using empirical data on knowledge, skill, attitudes, aptitude and beliefs to refine programs and improve student learning." .

ea:Examiner a owl:Class ; rdfs:label "Examiner" .
ea:ExpertExaminer a owl:Class ; rdfs:subClassOf ea:Examiner .
ea:Candidate a owl:Class ; rdfs:label "Candidate" ; skos:altLabel "test taker", "examinee" .

ea:hasExaminer a owl:ObjectProperty ; rdfs:domain ea:Assessment ; rdfs:range ea:Examiner .
ea:hasCandidate a owl:ObjectProperty ; rdfs:domain ea:Assessment ; rdfs:range ea:Candidate .

ea:LearningOutcome a owl:Class ; rdfs:label "Learning Outcome" .
ea:hasLearningOutcome a owl:ObjectProperty ; rdfs:domain ea:Assessment ; rdfs:range ea:LearningOutcome .

#################################################################
# AXIS 1: PURPOSE  (Placement / Formative / Summative / Diagnostic)
#################################################################

ea:hasPurpose a owl:ObjectProperty, owl:FunctionalProperty ;
  rdfs:domain ea:Assessment ; rdfs:range ea:PurposeCategory .

ea:PurposeCategory a owl:Class .
ea:PlacementPurpose   a owl:Class ; rdfs:subClassOf ea:PurposeCategory .
ea:FormativePurpose   a owl:Class ; rdfs:subClassOf ea:PurposeCategory .
ea:SummativePurpose   a owl:Class ; rdfs:subClassOf ea:PurposeCategory .
ea:DiagnosticPurpose  a owl:Class ; rdfs:subClassOf ea:PurposeCategory .

ea:PurposeCategory owl:disjointUnionOf
  ( ea:PlacementPurpose ea:FormativePurpose ea:SummativePurpose ea:DiagnosticPurpose ) .

ea:PlacementAssessment a owl:Class ;
  rdfs:label "Placement Assessment" ;
  skos:altLabel "pre-assessment", "initial assessment", "threshold knowledge test", "TKT" ;
  owl:equivalentClass [ owl:intersectionOf ( ea:Assessment
    [ a owl:Restriction ; owl:onProperty ea:hasPurpose ; owl:someValuesFrom ea:PlacementPurpose ] ) ] .

ea:FormativeAssessment a owl:Class ;
  rdfs:label "Formative Assessment" ;
  skos:altLabel "formative evaluation", "educative assessment", "assessment for learning", "classroom assessment" ;
  owl:equivalentClass [ owl:intersectionOf ( ea:Assessment
    [ a owl:Restriction ; owl:onProperty ea:hasPurpose ; owl:someValuesFrom ea:FormativePurpose ] ) ] .

ea:SummativeAssessment a owl:Class ;
  rdfs:label "Summative Assessment" ;
  skos:altLabel "summative evaluation", "assessment of learning" ;
  owl:equivalentClass [ owl:intersectionOf ( ea:Assessment
    [ a owl:Restriction ; owl:onProperty ea:hasPurpose ; owl:someValuesFrom ea:SummativePurpose ] ) ] .

ea:DiagnosticAssessment a owl:Class ;
  rdfs:label "Diagnostic Assessment" ;
  skos:altLabel "diagnostic testing" ;
  owl:equivalentClass [ owl:intersectionOf ( ea:Assessment
    [ a owl:Restriction ; owl:onProperty ea:hasPurpose ; owl:someValuesFrom ea:DiagnosticPurpose ] ) ] ;
  rdfs:subClassOf ea:FormativeAssessment ;
  rdfs:comment "TENSION: one passage lists Placement, Formative, Summative and Diagnostic as four coordinate (mutually exclusive, via PurposeCategory disjoint union) categories of assessment, while another passage states 'A common form of formative assessment is diagnostic assessment', subordinating Diagnostic under Formative. Both claims are encoded: DiagnosticAssessment is a disjoint sibling value-class bridge AND a subClassOf FormativeAssessment." .

ea:SelfAssessment a owl:Class ;
  rdfs:subClassOf ea:DiagnosticAssessment ;
  rdfs:comment "Self-assessment is a form of diagnostic assessment in which students assess themselves." .

ea:ForwardLookingAssessment a owl:Class ;
  rdfs:subClassOf ea:Assessment ;
  rdfs:comment "Forward-looking assessment asks those being assessed to consider themselves in hypothetical future situations." .

#################################################################
# AXIS 2: RESPONSE TYPE (Objective / Subjective)
#################################################################

ea:hasResponseType a owl:ObjectProperty, owl:FunctionalProperty ;
  rdfs:domain ea:Assessment ; rdfs:range ea:ResponseCategory .

ea:ResponseCategory a owl:Class .
ea:ObjectiveResponse  a owl:Class ; rdfs:subClassOf ea:ResponseCategory .
ea:SubjectiveResponse a owl:Class ; rdfs:subClassOf ea:ResponseCategory .
ea:ResponseCategory owl:disjointUnionOf ( ea:ObjectiveResponse ea:SubjectiveResponse ) .

ea:ObjectiveAssessment a owl:Class ;
  owl:equivalentClass [ owl:intersectionOf ( ea:Assessment
    [ a owl:Restriction ; owl:onProperty ea:hasResponseType ; owl:someValuesFrom ea:ObjectiveResponse ] ) ] ;
  rdfs:comment "A form of questioning that has a single correct answer." .

ea:SubjectiveAssessment a owl:Class ;
  owl:equivalentClass [ owl:intersectionOf ( ea:Assessment
    [ a owl:Restriction ; owl:onProperty ea:hasResponseType ; owl:someValuesFrom ea:SubjectiveResponse ] ) ] ;
  rdfs:comment "A form of questioning that may have more than one correct answer." .

#################################################################
# AXIS 3: REFERENCING (Criterion / Norm / Ipsative)
#################################################################

ea:hasReferencingType a owl:ObjectProperty, owl:FunctionalProperty ;
  rdfs:domain ea:Assessment ; rdfs:range ea:ReferencingCategory .

ea:ReferencingCategory a owl:Class .
ea:CriterionReferencing a owl:Class ; rdfs:subClassOf ea:ReferencingCategory .
ea:NormReferencing      a owl:Class ; rdfs:subClassOf ea:ReferencingCategory .
ea:IpsativeReferencing  a owl:Class ; rdfs:subClassOf ea:ReferencingCategory .
ea:ReferencingCategory owl:disjointUnionOf
  ( ea:CriterionReferencing ea:NormReferencing ea:IpsativeReferencing ) .

ea:CriterionReferencedAssessment a owl:Class ;
  skos:altLabel "standards-based assessment" ;
  owl:equivalentClass [ owl:intersectionOf ( ea:Assessment
    [ a owl:Restriction ; owl:onProperty ea:hasReferencingType ; owl:someValuesFrom ea:CriterionReferencing ] ) ] .

ea:NormReferencedAssessment a owl:Class ;
  skos:altLabel "normative assessment", "grading on the curve" ;
  owl:equivalentClass [ owl:intersectionOf ( ea:Assessment
    [ a owl:Restriction ; owl:onProperty ea:hasReferencingType ; owl:someValuesFrom ea:NormReferencing ] ) ] .

ea:IpsativeAssessment a owl:Class ;
  skos:altLabel "self-referenced assessment" ;
  owl:equivalentClass [ owl:intersectionOf ( ea:Assessment
    [ a owl:Restriction ; owl:onProperty ea:hasReferencingType ; owl:someValuesFrom ea:IpsativeReferencing ] ) ] ;
  rdfs:comment "Self-comparison either in the same domain over time, or comparative to other domains within the same student." .

#################################################################
# AXIS 4: FORMALITY (Formal / Informal)
#################################################################

ea:hasFormality a owl:ObjectProperty, owl:FunctionalProperty ;
  rdfs:domain ea:Assessment ; rdfs:range ea:FormalityCategory .

ea:FormalityCategory a owl:Class .
ea:FormalManner   a owl:Class ; rdfs:subClassOf ea:FormalityCategory .
ea:InformalManner a owl:Class ; rdfs:subClassOf ea:FormalityCategory .
ea:FormalityCategory owl:disjointUnionOf ( ea:FormalManner ea:InformalManner ) .

ea:FormalAssessment a owl:Class ;
  owl:equivalentClass [ owl:intersectionOf ( ea:Assessment
    [ a owl:Restriction ; owl:onProperty ea:hasFormality ; owl:someValuesFrom ea:FormalManner ] ) ] .

ea:InformalAssessment a owl:Class ;
  owl:equivalentClass [ owl:intersectionOf ( ea:Assessment
    [ a owl:Restriction ; owl:onProperty ea:hasFormality ; owl:someValuesFrom ea:InformalManner ] ) ] .

#################################################################
# AXIS 5: LOCUS (Internal / External)
#################################################################

ea:hasLocus a owl:ObjectProperty, owl:FunctionalProperty ;
  rdfs:domain ea:Assessment ; rdfs:range ea:LocusCategory .

ea:LocusCategory a owl:Class .
ea:InternalLocus a owl:Class ; rdfs:subClassOf ea:LocusCategory .
ea:ExternalLocus a owl:Class ; rdfs:subClassOf ea:LocusCategory .
ea:LocusCategory owl:disjointUnionOf ( ea:InternalLocus ea:ExternalLocus ) .

ea:InternalAssessment a owl:Class ;
  owl:equivalentClass [ owl:intersectionOf ( ea:Assessment
    [ a owl:Restriction ; owl:onProperty ea:hasLocus ; owl:someValuesFrom ea:InternalLocus ] ) ] ;
  rdfs:comment "Set and marked by the school (teachers)." .

ea:ExternalAssessment a owl:Class ;
  owl:equivalentClass [ owl:intersectionOf ( ea:Assessment
    [ a owl:Restriction ; owl:onProperty ea:hasLocus ; owl:someValuesFrom ea:ExternalLocus ] ) ] ;
  rdfs:comment "Set by the governing body and marked by unbiased personnel." .

#################################################################
# TEST (examination) AND ITS AXES
#################################################################

ea:Test a owl:Class ;
  rdfs:subClassOf ea:Assessment ;
  rdfs:label "Test" ;
  skos:altLabel "examination", "exam", "evaluation" ;
  rdfs:comment "An educational assessment intended to measure a test-taker's knowledge, skill, aptitude, physical fitness, or classification in some other topic." .

### Standardization axis
ea:hasStandardization a owl:ObjectProperty, owl:FunctionalProperty ;
  rdfs:domain ea:Test ; rdfs:range ea:StandardizationCategory .

ea:StandardizationCategory a owl:Class .
ea:StandardizedManner    a owl:Class ; rdfs:subClassOf ea:StandardizationCategory .
ea:NonStandardizedManner a owl:Class ; rdfs:subClassOf ea:StandardizationCategory .
ea:StandardizationCategory owl:disjointUnionOf ( ea:StandardizedManner ea:NonStandardizedManner ) .

ea:StandardizedTest a owl:Class ;
  owl:equivalentClass [ owl:intersectionOf ( ea:Test
    [ a owl:Restriction ; owl:onProperty ea:hasStandardization ; owl:someValuesFrom ea:StandardizedManner ] ) ] ;
  rdfs:comment "A test that is administered and scored in a consistent or standard manner." .

ea:NonStandardizedTest a owl:Class ;
  owl:equivalentClass [ owl:intersectionOf ( ea:Test
    [ a owl:Restriction ; owl:onProperty ea:hasStandardization ; owl:someValuesFrom ea:NonStandardizedManner ] ) ] ;
  rdfs:comment "Significantly different tests are given, or the same test is given under significantly different conditions or evaluated differently." .

### Stakes axis
ea:hasStakes a owl:ObjectProperty, owl:FunctionalProperty ;
  rdfs:domain ea:Test ; rdfs:range ea:StakesCategory .

ea:StakesCategory a owl:Class .
ea:HighStakesValue a owl:Class ; rdfs:subClassOf ea:StakesCategory .
ea:LowStakesValue  a owl:Class ; rdfs:subClassOf ea:StakesCategory .
ea:StakesCategory owl:disjointUnionOf ( ea:HighStakesValue ea:LowStakesValue ) .

ea:HighStakesTest a owl:Class ;
  owl:equivalentClass [ owl:intersectionOf ( ea:Test
    [ a owl:Restriction ; owl:onProperty ea:hasStakes ; owl:someValuesFrom ea:HighStakesValue ] ) ] ;
  rdfs:comment "A test with a desired reward for good performance, or important consequences for the examinee." .

ea:LowStakesTest a owl:Class ;
  owl:equivalentClass [ owl:intersectionOf ( ea:Test
    [ a owl:Restriction ; owl:onProperty ea:hasStakes ; owl:someValuesFrom ea:LowStakesValue ] ) ] .

### Administration-mode axis
ea:hasAdministrationMode a owl:ObjectProperty, owl:FunctionalProperty ;
  rdfs:domain ea:Test ; rdfs:range ea:AdministrationModeCategory .

ea:AdministrationModeCategory a owl:Class .
ea:WrittenMode   a owl:Class ; rdfs:subClassOf ea:AdministrationModeCategory .
ea:OralMode      a owl:Class ; rdfs:subClassOf ea:AdministrationModeCategory .
ea:PracticalMode a owl:Class ; rdfs:subClassOf ea:AdministrationModeCategory .
ea:ComputerMode  a owl:Class ; rdfs:subClassOf ea:AdministrationModeCategory .
ea:AdministrationModeCategory owl:disjointUnionOf
  ( ea:WrittenMode ea:OralMode ea:PracticalMode ea:ComputerMode ) .

ea:WrittenTest a owl:Class ;
  owl:equivalentClass [ owl:intersectionOf ( ea:Test
    [ a owl:Restriction ; owl:onProperty ea:hasAdministrationMode ; owl:someValuesFrom ea:WrittenMode ] ) ] .

ea:OralTest a owl:Class ;
  owl:equivalentClass [ owl:intersectionOf ( ea:Test
    [ a owl:Restriction ; owl:onProperty ea:hasAdministrationMode ; owl:someValuesFrom ea:OralMode ] ) ] .

ea:PracticalTest a owl:Class ;
  owl:equivalentClass [ owl:intersectionOf ( ea:Test
    [ a owl:Restriction ; owl:onProperty ea:hasAdministrationMode ; owl:someValuesFrom ea:PracticalMode ] ) ] .

ea:ComputerBasedTest a owl:Class ;
  skos:altLabel "eExam" ;
  owl:equivalentClass [ owl:intersectionOf ( ea:Test
    [ a owl:Restriction ; owl:onProperty ea:hasAdministrationMode ; owl:someValuesFrom ea:ComputerMode ] ) ] ;
  rdfs:subClassOf ea:WrittenTest ;
  rdfs:comment "TENSION: one passage treats 'on a computer' as a fourth mode coordinate with verbal/paper/practical, while another passage ('Written tests are tests administered on paper or on a computer') subsumes computer-based testing under written tests. Both are encoded: ComputerMode is a disjoint sibling in AdministrationModeCategory AND ComputerBasedTest is declared subClassOf WrittenTest." .

#################################################################
# TEST SUBCLASSES
#################################################################

ea:Quiz a owl:Class ; rdfs:subClassOf ea:Test ;
  rdfs:comment "A brief assessment covering a small amount of material; usually low-stakes and formative." .

ea:MidtermExamination a owl:Class ; rdfs:subClassOf ea:Test ;
  rdfs:comment "An exam given near the middle of an academic term. Stated to be 'a type of formative or summative assessment', i.e. it is not fixed to a single value on the Purpose axis." .

ea:FinalExamination a owl:Class ; rdfs:subClassOf ea:Test ;
  rdfs:comment "A final review and assessment of topics covered in a course; typically summative." ;
  rdfs:subClassOf ea:SummativeAssessment .

ea:CriterionReferencedTest a owl:Class ;
  skos:altLabel "CRT" ;
  owl:equivalentClass [ owl:intersectionOf ( ea:Test
    [ a owl:Restriction ; owl:onProperty ea:hasReferencingType ; owl:someValuesFrom ea:CriterionReferencing ] ) ] ;
  rdfs:comment "Measures test takers against defined, objective criteria regardless of other test takers' scores." .

ea:NormReferencedTest a owl:Class ;
  skos:altLabel "NRT" ;
  owl:equivalentClass [ owl:intersectionOf ( ea:Test
    [ a owl:Restriction ; owl:onProperty ea:hasReferencingType ; owl:someValuesFrom ea:NormReferencing ] ) ] ;
  rdfs:comment "Yields an estimate of the position of the tested individual in a predefined population." .

ea:MasteryTest a owl:Class ; rdfs:subClassOf ea:CriterionReferencedTest ;
  rdfs:comment "A criterion-referenced test with a cutscore; examinee passes if score exceeds cutscore." .

ea:hasCutScore a owl:DatatypeProperty, owl:FunctionalProperty ;
  rdfs:domain ea:CriterionReferencedTest ; rdfs:range xsd:decimal .

ea:CompetitiveExamination a owl:Class ;
  rdfs:comment "Norm-referenced, high-stakes tests in which candidates are ranked and only the top n candidates pass." ;
  owl:equivalentClass [ owl:intersectionOf ( ea:Test
    [ a owl:Restriction ; owl:onProperty ea:hasReferencingType ; owl:someValuesFrom ea:NormReferencing ]
    [ a owl:Restriction ; owl:onProperty ea:hasStakes ; owl:someValuesFrom ea:HighStakesValue ] ) ] .

ea:AchievementTest a owl:Class ; rdfs:subClassOf ea:StandardizedTest ;
  rdfs:comment "Measures knowledge and skills students learned in school; 'backward-looking'." .
ea:AptitudeTest a owl:Class ; rdfs:subClassOf ea:StandardizedTest ;
  rdfs:comment "Attempts to predict a student's ability to succeed; 'forward-looking'." .
ea:CollegeAdmissionTest a owl:Class ; rdfs:subClassOf ea:StandardizedTest .
ea:InternationalComparisonTest a owl:Class ; rdfs:subClassOf ea:StandardizedTest .
ea:PsychologicalTest a owl:Class ; rdfs:subClassOf ea:StandardizedTest .

owl:AllDisjointClasses [ owl:members
  ( ea:AchievementTest ea:AptitudeTest ea:CollegeAdmissionTest
    ea:InternationalComparisonTest ea:PsychologicalTest ) ] .

ea:PerformanceTest a owl:Class ; rdfs:subClassOf ea:Test ;
  rdfs:comment "Requires an examinee to actually perform a task or activity rather than answer questions about it." .

#################################################################
# OTHER ASSESSMENT KINDS
#################################################################

ea:PerformanceBasedAssessment a owl:Class ; rdfs:subClassOf ea:Assessment ;
  rdfs:comment "Focuses on achievement through a well-defined task; students create, produce, or do something, often with real-world application." .

ea:hasOutcomeFormat a owl:ObjectProperty, owl:FunctionalProperty ;
  rdfs:domain ea:PerformanceBasedAssessment ; rdfs:range ea:OutcomeFormatCategory .
ea:OutcomeFormatCategory a owl:Class .
ea:ProductOutcome a owl:Class ; rdfs:subClassOf ea:OutcomeFormatCategory .
ea:PerformanceOutcome a owl:Class ; rdfs:subClassOf ea:OutcomeFormatCategory .
ea:OutcomeFormatCategory owl:disjointUnionOf ( ea:ProductOutcome ea:PerformanceOutcome ) .

ea:ProductAssessment a owl:Class ;
  owl:equivalentClass [ owl:intersectionOf ( ea:PerformanceBasedAssessment
    [ a owl:Restriction ; owl:onProperty ea:hasOutcomeFormat ; owl:someValuesFrom ea:ProductOutcome ] ) ] .
ea:LivePerformanceAssessment a owl:Class ;
  owl:equivalentClass [ owl:intersectionOf ( ea:PerformanceBasedAssessment
    [ a owl:Restriction ; owl:onProperty ea:hasOutcomeFormat ; owl:someValuesFrom ea:PerformanceOutcome ] ) ] .

ea:AuthenticAssessment a owl:Class ; rdfs:subClassOf ea:Assessment ;
  rdfs:comment "Measurement of accomplishments within a realistic, practical context relevant outside school." ;
  owl:equivalentClass ea:PerformanceBasedAssessment ;
  rdfs:comment "TENSION: one Glossary passage states 'Performance assessments may also be called authentic assessments' (equivalence), while an enumerated 'Assessment types' list presents 'Performance-based assessments' and 'Authentic assessment' as two separate coordinate bullet items. Both readings are encoded: equivalentClass captures the synonym claim." .

ea:ContinuousAssessment a owl:Class ; rdfs:subClassOf ea:Assessment ;
  rdfs:comment "Evaluates a student's progress throughout a prescribed course; often includes formative assessment." .

ea:PortfolioAssessment a owl:Class ; rdfs:subClassOf ea:Assessment ;
  skos:altLabel "portfolio-based assessment" ;
  rdfs:comment "Compilation of academic work assembled to evaluate learning progress and achievement over time." .

ea:Rubric a owl:Class ; rdfs:label "Rubric" ;
  rdfs:comment "A scoring guide used to evaluate the quality of students' constructed responses." .
ea:hasRubric a owl:ObjectProperty ; rdfs:domain ea:Assessment ; rdfs:range ea:Rubric .

ea:ComplexAssessment a owl:Class ;
  rdfs:comment "Requires a rubric and an expert examiner, e.g. thesis or funding proposal." ;
  owl:equivalentClass [ owl:intersectionOf ( ea:Assessment
    [ a owl:Restriction ; owl:onProperty ea:hasRubric ; owl:someValuesFrom ea:Rubric ]
    [ a owl:Restriction ; owl:onProperty ea:hasExaminer ; owl:someValuesFrom ea:ExpertExaminer ] ) ] .

ea:TeacherEvaluation a owl:Class ; rdfs:subClassOf ea:Assessment ;
  rdfs:comment "Summative assessment can be used to refer to assessment of educational faculty by their supervisor." ;
  rdfs:subClassOf ea:SummativeAssessment .

ea:ValueAddedMeasure a owl:Class ; rdfs:subClassOf ea:TeacherEvaluation ;
  skos:altLabel "growth measure" .
ea:StudentGrowthMeasure a owl:Class ; rdfs:subClassOf ea:TeacherEvaluation .

#################################################################
# TEST ITEMS
#################################################################

ea:TestItem a owl:Class ; rdfs:label "Test Item" ;
  skos:altLabel "question" ;
  rdfs:comment "The general term for a component of a test; many items are not phrased as questions." .

ea:hasItem a owl:ObjectProperty ; rdfs:domain ea:Test ; rdfs:range ea:TestItem .
ea:isItemOf a owl:ObjectProperty ; owl:inverseOf ea:hasItem ; rdfs:domain ea:TestItem ; rdfs:range ea:Test .

ea:ObjectiveItem  a owl:Class ; rdfs:subClassOf ea:TestItem .
ea:SubjectiveItem a owl:Class ; rdfs:subClassOf ea:TestItem .
ea:ObjectiveItem owl:disjointWith ea:SubjectiveItem .

ea:TrueFalseItem a owl:Class ; rdfs:subClassOf ea:ObjectiveItem .
ea:MultipleChoiceItem a owl:Class ; rdfs:subClassOf ea:ObjectiveItem ;
  skos:altLabel "MCQ", "objective response" .
ea:MultipleResponseItem a owl:Class ; rdfs:subClassOf ea:ObjectiveItem ;
  rdfs:comment "More than one answer may be keyed as correct, unlike MultipleChoiceItem." .
ea:MatchingItem a owl:Class ; rdfs:subClassOf ea:ObjectiveItem .

owl:AllDisjointClasses [ owl:members
  ( ea:TrueFalseItem ea:MultipleChoiceItem ea:MultipleResponseItem ea:MatchingItem ) ] .

ea:TrueFalseItem rdfs:subClassOf ea:MultipleChoiceItem ;
  rdfs:comment "TENSION: one passage lists True/False as a sibling objective-item type coordinate with (and disjoint from) Multiple-Choice, while another passage states 'There are two families of multiple-choice questions. The first family is known as the True/False question', subordinating True/False under Multiple-Choice. Both are encoded." .

ea:ExtendedResponseItem a owl:Class ; rdfs:subClassOf ea:SubjectiveItem .
ea:EssayItem a owl:Class ; rdfs:subClassOf ea:SubjectiveItem ;
  skos:altLabel "free response question", "FRQ", "free response item" .
ea:ShortAnswerItem a owl:Class ; rdfs:subClassOf ea:SubjectiveItem .
ea:FillInTheBlankItem a owl:Class ; rdfs:subClassOf ea:TestItem .

owl:AllDisjointClasses [ owl:members ( ea:ExtendedResponseItem ea:EssayItem ea:ShortAnswerItem ) ] .

### Multiple-choice internal structure
ea:Stem a owl:Class ; rdfs:comment "The opening of an item: a problem, question, or incomplete statement." .
ea:AnswerOption a owl:Class .
ea:Key a owl:Class ; rdfs:subClassOf ea:AnswerOption ; rdfs:comment "The correct answer." .
ea:Distractor a owl:Class ; rdfs:subClassOf ea:AnswerOption ; rdfs:comment "An incorrect answer option." .
ea:Key owl:disjointWith ea:Distractor .

ea:hasStem a owl:ObjectProperty, owl:FunctionalProperty ;
  rdfs:domain ea:MultipleChoiceItem ; rdfs:range ea:Stem .
ea:hasAnswerOption a owl:ObjectProperty ; rdfs:domain ea:MultipleChoiceItem ; rdfs:range ea:AnswerOption .
ea:hasKey a owl:ObjectProperty ; rdfs:subPropertyOf ea:hasAnswerOption ;
  rdfs:domain ea:MultipleChoiceItem ; rdfs:range ea:Key .
ea:hasDistractor a owl:ObjectProperty ; rdfs:subPropertyOf ea:hasAnswerOption ;
  rdfs:domain ea:MultipleChoiceItem ; rdfs:range ea:Distractor .

ea:MultipleChoiceItem rdfs:subClassOf
  [ a owl:Restriction ; owl:onProperty ea:hasKey ; owl:qualifiedCardinality 1 ; owl:onClass ea:Key ] .
ea:MultipleResponseItem rdfs:subClassOf
  [ a owl:Restriction ; owl:onProperty ea:hasKey ; owl:minQualifiedCardinality 2 ; owl:onClass ea:Key ] .

#################################################################
# VALIDITY
#################################################################

ea:ValidityEvidence a owl:Class ; rdfs:label "Validity Evidence" ;
  rdfs:comment "Evidence of the degree to which an assessment measures what it is intended to measure." .

ea:hasValidityEvidence a owl:ObjectProperty ; rdfs:domain ea:Assessment ; rdfs:range ea:ValidityEvidence .

ea:ContentValidityEvidence a owl:Class ; rdfs:subClassOf ea:ValidityEvidence ;
  skos:altLabel "logical validity" ;
  rdfs:comment "Does the content of the test measure stated objectives / cover a representative sample of the behaviour domain?" .

ea:CriterionValidityEvidence a owl:Class ; rdfs:subClassOf ea:ValidityEvidence ;
  skos:altLabel "criterion-related validity" ;
  rdfs:comment "The extent to which the test relates to, or predicts, a theoretically related criterion." .

ea:ConcurrentValidityEvidence a owl:Class ; rdfs:subClassOf ea:CriterionValidityEvidence ;
  rdfs:comment "Test data and criterion data are collected at the same time." .
ea:PredictiveValidityEvidence a owl:Class ; rdfs:subClassOf ea:CriterionValidityEvidence ;
  rdfs:comment "Test data are collected first to predict criterion data collected later." .
ea:ConcurrentValidityEvidence owl:disjointWith ea:PredictiveValidityEvidence .

ea:ConstructValidityEvidence a owl:Class ; rdfs:subClassOf ea:ValidityEvidence ;
  rdfs:comment "The extent to which operationalizations of a construct measure the construct as defined by theory." .

ea:ConvergentValidityEvidence a owl:Class ; rdfs:subClassOf ea:ConstructValidityEvidence .
ea:DiscriminantValidityEvidence a owl:Class ; rdfs:subClassOf ea:ConstructValidityEvidence .
ea:ConvergentValidityEvidence owl:disjointWith ea:DiscriminantValidityEvidence .

ea:FaceValidityEvidence a owl:Class ; rdfs:subClassOf ea:ValidityEvidence ;
  rdfs:comment "Whether a test appears, on its face, to measure what it purports to measure." .
ea:ConsequentialValidityEvidence a owl:Class ; rdfs:subClassOf ea:ValidityEvidence .

ea:ContentValidityEvidence rdfs:subClassOf ea:ConstructValidityEvidence .
ea:CriterionValidityEvidence rdfs:subClassOf ea:ConstructValidityEvidence .
ea:FaceValidityEvidence rdfs:subClassOf ea:ConstructValidityEvidence .
ea:ConsequentialValidityEvidence rdfs:subClassOf ea:ConstructValidityEvidence .

ea:ConstructValidityEvidence rdfs:comment "TENSION: one passage lists content, criterion, construct, consequential and face validity as coordinate categories of validity evidence, while another states 'Construct validity ... subsumes all other types of validity' and 'Modern validity theory defines construct validity as the overarching concern of validity research, subsuming all other types'. Both are encoded: the coordinate siblings AND the subsumption (subClassOf) relations." .

ea:hasValidityCoefficient a owl:DatatypeProperty ; rdfs:domain ea:ValidityEvidence ; rdfs:range xsd:decimal .

#################################################################
# RELIABILITY
#################################################################

ea:Reliability a owl:Class ; rdfs:label "Reliability" ;
  rdfs:comment "The consistency of an assessment; freedom of a measure from measurement error." .

ea:hasReliabilityEstimate a owl:ObjectProperty ; rdfs:domain ea:Assessment ; rdfs:range ea:Reliability .
ea:hasReliabilityCoefficient a owl:DatatypeProperty ; rdfs:domain ea:Reliability ; rdfs:range xsd:decimal ;
  rdfs:comment "Ranges from 0.00 (much error) to 1.00 (no error)." .

ea:TestRetestReliability a owl:Class ; rdfs:subClassOf ea:Reliability ;
  skos:altLabel "repeatability" ;
  rdfs:comment "Assesses the degree to which test scores are consistent from one administration to the next." .

ea:InterRaterReliability a owl:Class ; rdfs:subClassOf ea:Reliability ;
  rdfs:comment "Degree of agreement between two or more raters." .

ea:InterMethodReliability a owl:Class ; rdfs:subClassOf ea:Reliability ;
  rdfs:comment "Degree to which test scores are consistent when there is variation in the methods/instruments used." .

ea:ParallelFormsReliability a owl:Class ; rdfs:subClassOf ea:InterMethodReliability ;
  skos:altLabel "alternate-forms reliability", "equivalent-forms reliability", "form equivalence" ;
  rdfs:comment "When dealing with forms, inter-method reliability may be termed parallel-forms reliability." .

ea:SplitHalfReliability a owl:Class ; rdfs:subClassOf ea:ParallelFormsReliability ;
  rdfs:comment "Treats the two halves of a measure as alternate forms." .

ea:InternalConsistencyReliability a owl:Class ; rdfs:subClassOf ea:Reliability ;
  rdfs:comment "Assesses consistency of results across items within a test (e.g. Cronbach's alpha)." .

owl:AllDisjointClasses [ owl:members
  ( ea:TestRetestReliability ea:InterRaterReliability ea:InterMethodReliability ea:InternalConsistencyReliability ) ] .

### Separate, conflicting four-part scheme based on error SOURCE rather than estimation method
ea:ReliabilitySource a owl:Class ;
  rdfs:comment "TENSION: the corpus gives two different 'four types of reliability' taxonomies. 'There are several general classes of reliability estimates' (test-retest, inter-rater, inter-method, internal consistency) is modeled as ea:Reliability. A separate passage states 'There are four types of reliability: student-related ... rater-related ... test administration-related ... and test-related', modeled here as the disjoint ea:ReliabilitySource partition. Both classification schemes are encoded." .

ea:StudentRelatedReliabilitySource a owl:Class ; rdfs:subClassOf ea:ReliabilitySource .
ea:RaterRelatedReliabilitySource a owl:Class ; rdfs:subClassOf ea:ReliabilitySource .
ea:TestAdministrationRelatedReliabilitySource a owl:Class ; rdfs:subClassOf ea:ReliabilitySource .
ea:TestRelatedReliabilitySource a owl:Class ; rdfs:subClassOf ea:ReliabilitySource .
ea:ReliabilitySource owl:disjointUnionOf
  ( ea:StudentRelatedReliabilitySource ea:RaterRelatedReliabilitySource
    ea:TestAdministrationRelatedReliabilitySource ea:TestRelatedReliabilitySource ) .

ea:hasReliabilitySource a owl:ObjectProperty ; rdfs:domain ea:Assessment ; rdfs:range ea:ReliabilitySource .

#################################################################
# RUBRIC TYPE AXIS
#################################################################

ea:hasRubricType a owl:ObjectProperty, owl:FunctionalProperty ;
  rdfs:domain ea:Rubric ; rdfs:range ea:RubricTypeCategory .

ea:RubricTypeCategory a owl:Class .
ea:HolisticRubricType a owl:Class ; rdfs:subClassOf ea:RubricTypeCategory .
ea:AnalyticRubricType a owl:Class ; rdfs:subClassOf ea:RubricTypeCategory .
ea:DevelopmentalRubricType a owl:Class ; rdfs:subClassOf ea:RubricTypeCategory .
ea:RubricTypeCategory owl:disjointUnionOf
  ( ea:HolisticRubricType ea:AnalyticRubricType ea:DevelopmentalRubricType ) .

ea:HolisticRubric a owl:Class ;
  owl:equivalentClass [ owl:intersectionOf ( ea:Rubric
    [ a owl:Restriction ; owl:onProperty ea:hasRubricType ; owl:someValuesFrom ea:HolisticRubricType ] ) ] ;
  rdfs:comment "Provides an overall rating for a piece of work, considering all aspects." .

ea:AnalyticRubric a owl:Class ;
  owl:equivalentClass [ owl:intersectionOf ( ea:Rubric
    [ a owl:Restriction ; owl:onProperty ea:hasRubricType ; owl:someValuesFrom ea:AnalyticRubricType ] ) ] ;
  rdfs:comment "Evaluates various dimensions or components separately." .

ea:DevelopmentalRubric a owl:Class ;
  owl:equivalentClass [ owl:intersectionOf ( ea:Rubric
    [ a owl:Restriction ; owl:onProperty ea:hasRubricType ; owl:someValuesFrom ea:DevelopmentalRubricType ] ) ] ;
  rdfs:subClassOf ea:AnalyticRubric ;
  rdfs:comment "TENSION: rubrics are classified as holistic, analytic, OR developmental (coordinate, disjoint, per 'Rubrics can be classified as holistic, analytic, or developmental'), yet the same passage calls 'Developmental rubrics ... a subset of analytical rubrics'. Both the disjoint coordinate reading and the subClassOf(AnalyticRubric) reading are encoded." .

#################################################################
# GRADING METHOD
#################################################################

ea:GradingMethod a owl:Class ; rdfs:label "Grading Method" .
ea:hasGradingMethod a owl:ObjectProperty ; rdfs:domain ea:Assessment ; rdfs:range ea:GradingMethod .

ea:HolisticGrading a owl:Class ; rdfs:subClassOf ea:GradingMethod ;
  skos:altLabel "holistic scoring", "nonreductionist grading" ;
  rdfs:comment "Bases a grade on a paper's overall quality; contrasts with analytic grading." .

ea:AnalyticGrading a owl:Class ; rdfs:subClassOf ea:GradingMethod ;
  rdfs:comment "Takes more factors into account, judging criterion by criterion." .
ea:HolisticGrading owl:disjointWith ea:AnalyticGrading .

ea:TraitInformedScoring a owl:Class ; rdfs:subClassOf ea:HolisticGrading ;
  rdfs:comment "Trains raters to score to a rubric with several criteria; 'comes close to analytic scoring methods' yet 'remains holistic at heart' -- i.e. it is placed under HolisticGrading despite resembling AnalyticGrading." .

