```turtle
@prefix ea:   <http://example.org/onto/assessment#> .
@prefix owl:  <http://www.w3.org/2002/07/owl#> .
@prefix rdf:  <http://www.w3.org/1999/02/22-rdf-syntax-ns#> .
@prefix rdfs: <http://www.w3.org/2000/01/rdf-schema#> .
@prefix xsd:  <http://www.w3.org/2001/XMLSchema#> .
@prefix skos: <http://www.w3.org/2004/02/skos/core#> .

<http://example.org/onto/assessment>
  a owl:Ontology ;
  rdfs:label "Educational Assessment Ontology" .

#################################################################
## TOP LEVEL
#################################################################

ea:EducationalAssessment a owl:Class ;
  rdfs:label "Educational Assessment" ;
  skos:altLabel "educational evaluation", "assessment" ;
  rdfs:comment "Systematic process of documenting and using empirical data on knowledge, skill, attitudes, aptitude and beliefs to refine programs and improve learning. Assessment is used interchangeably with 'test' but is broader than tests." .

ea:Test a owl:Class ;
  rdfs:subClassOf ea:EducationalAssessment ;
  rdfs:comment "Assessment is often used interchangeably with test but is not limited to tests." .

ea:Examination a owl:Class ;
  owl:equivalentClass ea:Test ;
  skos:altLabel "exam", "evaluation" ;
  rdfs:comment "An examination (exam or evaluation), or test, is an educational assessment intended to measure a test-taker's knowledge, skill, aptitude, physical fitness, or classification." .

ea:Quiz a owl:Class ; rdfs:subClassOf ea:Examination ;
  rdfs:comment "A brief assessment covering a small amount of material, commonly used formatively." .

ea:MidtermExamination a owl:Class ; rdfs:subClassOf ea:Examination ;
  skos:altLabel "midterm exam", "midterm" ;
  rdfs:comment "Given near the middle of a grading term. Corpus states it is 'a type of formative or summative assessment' - both purposes attested." .

ea:FinalExamination a owl:Class ; rdfs:subClassOf ea:Examination ;
  skos:altLabel "final exam", "final" .

#################################################################
## GRANULARITY
#################################################################

ea:hasGranularity a owl:ObjectProperty, owl:FunctionalProperty ;
  rdfs:domain ea:EducationalAssessment ;
  rdfs:range ea:GranularityCategory .

ea:GranularityCategory a owl:Class ;
  owl:disjointUnionOf ( ea:IndividualLearnerGranularity ea:LearningCommunityGranularity
                         ea:CourseGranularity ea:AcademicProgramGranularity
                         ea:InstitutionGranularity ea:EducationalSystemGranularity ) ;
  rdfs:comment "Assessment can focus on the individual learner, the learning community, a course, an academic program, the institution, or the educational system as a whole." .

ea:IndividualLearnerGranularity a owl:Class ; rdfs:subClassOf ea:GranularityCategory .
ea:LearningCommunityGranularity a owl:Class ; rdfs:subClassOf ea:GranularityCategory .
ea:CourseGranularity a owl:Class ; rdfs:subClassOf ea:GranularityCategory .
ea:AcademicProgramGranularity a owl:Class ; rdfs:subClassOf ea:GranularityCategory .
ea:InstitutionGranularity a owl:Class ; rdfs:subClassOf ea:GranularityCategory .
ea:EducationalSystemGranularity a owl:Class ; rdfs:subClassOf ea:GranularityCategory .

#################################################################
## AXIS 1: PURPOSE  (placement / formative / summative / diagnostic)
#################################################################

ea:hasPurpose a owl:ObjectProperty, owl:FunctionalProperty ;
  rdfs:domain ea:EducationalAssessment ;
  rdfs:range ea:PurposeCategory .

ea:PurposeCategory a owl:Class ;
  owl:disjointUnionOf ( ea:PlacementPurpose ea:FormativePurpose ea:SummativePurpose ea:DiagnosticPurpose ) ;
  rdfs:comment "Assessment can be divided into placement, formative, summative and diagnostic assessment (coordinate, mutually exclusive categories, per the categorisation passage)." .

ea:PlacementPurpose a owl:Class ; rdfs:subClassOf ea:PurposeCategory .
ea:FormativePurpose a owl:Class ; rdfs:subClassOf ea:PurposeCategory .
ea:SummativePurpose a owl:Class ; rdfs:subClassOf ea:PurposeCategory .
ea:DiagnosticPurpose a owl:Class ; rdfs:subClassOf ea:PurposeCategory .

ea:PlacementAssessment a owl:Class ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( ea:EducationalAssessment
      [ a owl:Restriction ; owl:onProperty ea:hasPurpose ; owl:someValuesFrom ea:PlacementPurpose ] ) ] ;
  skos:altLabel "pre-assessment", "initial assessment", "threshold knowledge test", "TKT" ;
  rdfs:comment "Used to place students according to prior achievement, level of knowledge, or personal characteristics before instruction. Generally not graded." .

ea:FormativeAssessment a owl:Class ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( ea:EducationalAssessment
      [ a owl:Restriction ; owl:onProperty ea:hasPurpose ; owl:someValuesFrom ea:FormativePurpose ] ) ] ;
  skos:altLabel "formative evaluation", "formative feedback", "assessment for learning", "educative assessment", "classroom assessment" ;
  rdfs:comment "Carried out during the course of learning to modify teaching and learning activities; 'when the cook tastes the soup'." .

ea:SummativeAssessment a owl:Class ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( ea:EducationalAssessment
      [ a owl:Restriction ; owl:onProperty ea:hasPurpose ; owl:someValuesFrom ea:SummativePurpose ] ) ] ;
  skos:altLabel "summative evaluation", "assessment of learning" ;
  rdfs:comment "Carried out at the end of a course or project; 'when the guest tastes the soup'." .

ea:DiagnosticAssessment a owl:Class ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( ea:EducationalAssessment
      [ a owl:Restriction ; owl:onProperty ea:hasPurpose ; owl:someValuesFrom ea:DiagnosticPurpose ] ) ] ;
  skos:altLabel "diagnostic testing" ;
  rdfs:subClassOf ea:FormativeAssessment ;
  rdfs:comment "TENSION: one passage lists diagnostic assessment as a coordinate, disjoint 4th category alongside placement/formative/summative (see ea:PurposeCategory disjointUnion). Another passage states 'a common form of formative assessment is diagnostic assessment', subordinating it to formative assessment. Both claims are modeled: the disjoint partition above, and this subClassOf axiom." .

ea:SelfAssessment a owl:Class ; rdfs:subClassOf ea:DiagnosticAssessment ;
  rdfs:comment "Self-assessment is a form of diagnostic assessment in which students assess themselves." .

ea:ForwardLookingAssessment a owl:Class ; rdfs:subClassOf ea:EducationalAssessment ;
  rdfs:comment "Asks those being assessed to consider themselves in hypothetical future situations." .

#################################################################
## AXIS 2: OBJECTIVITY
#################################################################

ea:hasObjectivity a owl:ObjectProperty, owl:FunctionalProperty ;
  rdfs:domain ea:EducationalAssessment ;
  rdfs:range ea:ObjectivityCategory .

ea:ObjectivityCategory a owl:Class ;
  owl:disjointUnionOf ( ea:ObjectiveCategory ea:SubjectiveCategory ) .

ea:ObjectiveCategory a owl:Class ; rdfs:subClassOf ea:ObjectivityCategory .
ea:SubjectiveCategory a owl:Class ; rdfs:subClassOf ea:ObjectivityCategory .

ea:ObjectiveAssessment a owl:Class ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( ea:EducationalAssessment
      [ a owl:Restriction ; owl:onProperty ea:hasObjectivity ; owl:someValuesFrom ea:ObjectiveCategory ] ) ] ;
  rdfs:comment "A form of questioning that has a single correct answer. Some scholars argue this distinction is 'neither useful nor accurate' because no assessment is purely objective - noted here, not resolved." .

ea:SubjectiveAssessment a owl:Class ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( ea:EducationalAssessment
      [ a owl:Restriction ; owl:onProperty ea:hasObjectivity ; owl:someValuesFrom ea:SubjectiveCategory ] ) ] ;
  rdfs:comment "A form of questioning that may have more than one correct answer or way of expressing it." .

#################################################################
## AXIS 3: REFERENCING  (criterion / norm / ipsative)
#################################################################

ea:hasReferencing a owl:ObjectProperty, owl:FunctionalProperty ;
  rdfs:domain ea:EducationalAssessment ;
  rdfs:range ea:ReferencingCategory .

ea:ReferencingCategory a owl:Class ;
  owl:disjointUnionOf ( ea:CriterionReferencing ea:NormReferencing ea:IpsativeReferencing ) ;
  rdfs:comment "One passage presents three coordinate referencing categories (criterion, norm, ipsative). Another passage states 'there are two types of test score interpretations: norm-referenced or criterion-referenced', omitting ipsative. Both are modeled: the three-way partition here, and ipsative assessment is additionally described elsewhere as contrasted with both." .

ea:CriterionReferencing a owl:Class ; rdfs:subClassOf ea:ReferencingCategory .
ea:NormReferencing a owl:Class ; rdfs:subClassOf ea:ReferencingCategory .
ea:IpsativeReferencing a owl:Class ; rdfs:subClassOf ea:ReferencingCategory .

ea:CriterionReferencedAssessment a owl:Class ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( ea:EducationalAssessment
      [ a owl:Restriction ; owl:onProperty ea:hasReferencing ; owl:someValuesFrom ea:CriterionReferencing ] ) ] ;
  skos:altLabel "CRT", "criterion-referenced test", "standards-based assessment" ;
  rdfs:comment "Candidates are measured against defined, objective criteria regardless of other examinees' scores. Robert Glaser coined the term. Example: the driving test." .

ea:NormReferencedAssessment a owl:Class ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( ea:EducationalAssessment
      [ a owl:Restriction ; owl:onProperty ea:hasReferencing ; owl:someValuesFrom ea:NormReferencing ] ) ] ;
  skos:altLabel "NRT", "norm-referenced test", "normative assessment", "grading on the curve", "curved grading", "bell curving" ;
  rdfs:comment "Compares test takers against each other / a predefined population; example: the IQ test." .

ea:IpsativeAssessment a owl:Class ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( ea:EducationalAssessment
      [ a owl:Restriction ; owl:onProperty ea:hasReferencing ; owl:someValuesFrom ea:IpsativeReferencing ] ) ] ;
  skos:altLabel "forced-choice assessment" ;
  rdfs:comment "Self-comparison either in the same domain over time, or across domains within the same student." .

ea:MasteryTest a owl:Class ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( ea:CriterionReferencedAssessment
      [ a owl:Restriction ; owl:onProperty ea:hasCutScore ; owl:someValuesFrom xsd:decimal ] ) ] ;
  rdfs:comment "A criterion-referenced test that involves a cutscore: examinee passes if score exceeds the cutscore." .

#################################################################
## AXIS 4: FORMALITY
#################################################################

ea:hasFormality a owl:ObjectProperty, owl:FunctionalProperty ;
  rdfs:domain ea:EducationalAssessment ;
  rdfs:range ea:FormalityCategory .

ea:FormalityCategory a owl:Class ;
  owl:disjointUnionOf ( ea:FormalCategory ea:InformalCategory ) .

ea:FormalCategory a owl:Class ; rdfs:subClassOf ea:FormalityCategory .
ea:InformalCategory a owl:Class ; rdfs:subClassOf ea:FormalityCategory .

ea:FormalAssessment a owl:Class ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( ea:EducationalAssessment
      [ a owl:Restriction ; owl:onProperty ea:hasFormality ; owl:someValuesFrom ea:FormalCategory ] ) ] ;
  rdfs:comment "Usually implies a written document, given a numerical score or grade." .

ea:InformalAssessment a owl:Class ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( ea:EducationalAssessment
      [ a owl:Restriction ; owl:onProperty ea:hasFormality ; owl:someValuesFrom ea:InformalCategory ] ) ] ;
  rdfs:comment "Occurs more casually; may include observation, inventories, checklists, rating scales, rubrics, performance and portfolio assessments, participation, peer and self-evaluation, discussion. Does not contribute to a final grade." .

#################################################################
## AXIS 5: ADMINISTRATION LOCUS (internal / external)
#################################################################

ea:hasAdministrationLocus a owl:ObjectProperty, owl:FunctionalProperty ;
  rdfs:domain ea:EducationalAssessment ;
  rdfs:range ea:AdministrationLocusCategory .

ea:AdministrationLocusCategory a owl:Class ;
  owl:disjointUnionOf ( ea:InternalLocus ea:ExternalLocus ) .

ea:InternalLocus a owl:Class ; rdfs:subClassOf ea:AdministrationLocusCategory .
ea:ExternalLocus a owl:Class ; rdfs:subClassOf ea:AdministrationLocusCategory .

ea:InternalAssessment a owl:Class ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( ea:EducationalAssessment
      [ a owl:Restriction ; owl:onProperty ea:hasAdministrationLocus ; owl:someValuesFrom ea:InternalLocus ] ) ] ;
  rdfs:comment "Set and marked by the school (teachers)." .

ea:ExternalAssessment a owl:Class ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( ea:EducationalAssessment
      [ a owl:Restriction ; owl:onProperty ea:hasAdministrationLocus ; owl:someValuesFrom ea:ExternalLocus ] ) ] ;
  rdfs:comment "Set by the governing body and marked by unbiased personnel." .

#################################################################
## AXIS 6: STANDARDIZATION
#################################################################

ea:hasStandardization a owl:ObjectProperty, owl:FunctionalProperty ;
  rdfs:domain ea:Test ;
  rdfs:range ea:StandardizationCategory .

ea:StandardizationCategory a owl:Class ;
  owl:disjointUnionOf ( ea:StandardizedCategory ea:NonStandardizedCategory ) .

ea:StandardizedCategory a owl:Class ; rdfs:subClassOf ea:StandardizationCategory .
ea:NonStandardizedCategory a owl:Class ; rdfs:subClassOf ea:StandardizationCategory .

ea:StandardizedTest a owl:Class ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( ea:Test
      [ a owl:Restriction ; owl:onProperty ea:hasStandardization ; owl:someValuesFrom ea:StandardizedCategory ] ) ] ;
  skos:altLabel "standardized assessment" ;
  rdfs:comment "Administered and scored in a consistent or standard manner for all test takers. Does not need to be high-stakes, time-limited, multiple-choice, or academic." .

ea:NonStandardizedTest a owl:Class ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( ea:Test
      [ a owl:Restriction ; owl:onProperty ea:hasStandardization ; owl:someValuesFrom ea:NonStandardizedCategory ] ) ] ;
  rdfs:comment "Flexible in scope and format, and variable in difficulty." .

ea:AchievementTest a owl:Class ; rdfs:subClassOf ea:StandardizedTest ;
  rdfs:comment "Measures knowledge/skills learned in school; 'backward-looking'. Most standardized tests are summative assessments (noted overlap with ea:SummativeAssessment)." .
ea:AptitudeTest a owl:Class ; rdfs:subClassOf ea:StandardizedTest ;
  rdfs:comment "Attempts to predict ability to succeed in an endeavour; 'forward-looking'." .
ea:CollegeAdmissionTest a owl:Class ; rdfs:subClassOf ea:StandardizedTest, ea:HighStakesTest .
ea:InternationalComparisonTest a owl:Class ; rdfs:subClassOf ea:StandardizedTest .
ea:PsychologicalTest a owl:Class ; rdfs:subClassOf ea:StandardizedTest .

[] a owl:AllDisjointClasses ;
   owl:members ( ea:AchievementTest ea:AptitudeTest ea:CollegeAdmissionTest
                 ea:InternationalComparisonTest ea:PsychologicalTest ) .

#################################################################
## AXIS 7: STAKES
#################################################################

ea:hasStakes a owl:ObjectProperty, owl:FunctionalProperty ;
  rdfs:domain ea:Test ;
  rdfs:range ea:StakesCategory .

ea:StakesCategory a owl:Class ;
  owl:disjointUnionOf ( ea:HighStakesCategory ea:LowStakesCategory ) .

ea:HighStakesCategory a owl:Class ; rdfs:subClassOf ea:StakesCategory .
ea:LowStakesCategory a owl:Class ; rdfs:subClassOf ea:StakesCategory .

ea:HighStakesTest a owl:Class ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( ea:Test
      [ a owl:Restriction ; owl:onProperty ea:hasStakes ; owl:someValuesFrom ea:HighStakesCategory ] ) ] ;
  rdfs:comment "A test with a desired reward for good performance; used to make important decisions about students, educators, schools, or districts." .

ea:LowStakesTest a owl:Class ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( ea:Test
      [ a owl:Restriction ; owl:onProperty ea:hasStakes ; owl:someValuesFrom ea:LowStakesCategory ] ) ] .

ea:CollegeAdmissionTest rdfs:comment "High-stakes, standardized; example of a test with multiple simultaneous classifications." .
ea:LicensureExamination a owl:Class ; rdfs:subClassOf ea:HighStakesTest .
ea:GraduationExamination a owl:Class ; rdfs:subClassOf ea:HighStakesTest .

ea:CompetitiveExamination a owl:Class ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf (
      ea:Examination
      [ a owl:Restriction ; owl:onProperty ea:hasReferencing ; owl:someValuesFrom ea:NormReferencing ]
      [ a owl:Restriction ; owl:onProperty ea:hasStakes ; owl:someValuesFrom ea:HighStakesCategory ] ) ] ;
  rdfs:comment "Norm-referenced, high-stakes tests in which candidates are ranked and top rankers selected, e.g. civil-service exams, entrance exams." .

#################################################################
## MODALITY (written / oral / practical)
#################################################################

ea:hasModality a owl:ObjectProperty, owl:FunctionalProperty ;
  rdfs:domain ea:Test ;
  rdfs:range ea:ModalityCategory .

ea:ModalityCategory a owl:Class ;
  owl:disjointUnionOf ( ea:WrittenModality ea:OralModality ea:PracticalModality ) ;
  rdfs:comment "A test may be administered verbally, on paper/computer, or in a predetermined area requiring demonstration; standardized tests can be written, oral, or practical." .

ea:WrittenModality a owl:Class ; rdfs:subClassOf ea:ModalityCategory .
ea:OralModality a owl:Class ; rdfs:subClassOf ea:ModalityCategory .
ea:PracticalModality a owl:Class ; rdfs:subClassOf ea:ModalityCategory .

ea:WrittenTest a owl:Class ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( ea:Test
      [ a owl:Restriction ; owl:onProperty ea:hasModality ; owl:someValuesFrom ea:WrittenModality ] ) ] .

ea:OralTest a owl:Class ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( ea:Test
      [ a owl:Restriction ; owl:onProperty ea:hasModality ; owl:someValuesFrom ea:OralModality ] ) ] .

ea:PerformanceTest a owl:Class ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( ea:Test
      [ a owl:Restriction ; owl:onProperty ea:hasModality ; owl:someValuesFrom ea:PracticalModality ] ) ] ;
  skos:altLabel "practical test" ;
  rdfs:comment "Requires the examinee to actually perform a task or activity (e.g. a behind-the-wheel driving test) rather than answer questions about it." .

#################################################################
## CONTEXT (authentic assessment) & OUTPUT FORMAT (performance assessment)
#################################################################

ea:hasContext a owl:ObjectProperty, owl:FunctionalProperty ;
  rdfs:domain ea:EducationalAssessment ;
  rdfs:range ea:AssessmentContextCategory .

ea:AssessmentContextCategory a owl:Class ;
  owl:disjointUnionOf ( ea:RealisticContext ea:ClassroomContext ) .

ea:RealisticContext a owl:Class ; rdfs:subClassOf ea:AssessmentContextCategory .
ea:ClassroomContext a owl:Class ; rdfs:subClassOf ea:AssessmentContextCategory .

ea:AuthenticAssessment a owl:Class ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( ea:EducationalAssessment
      [ a owl:Restriction ; owl:onProperty ea:hasContext ; owl:someValuesFrom ea:RealisticContext ] ) ] ;
  rdfs:comment "Measurement of accomplishments within a realistic, practical context relevant outside the school setting." .

ea:hasOutputFormat a owl:ObjectProperty, owl:FunctionalProperty ;
  rdfs:domain ea:EducationalAssessment ;
  rdfs:range ea:PerformanceOutputCategory .

ea:PerformanceOutputCategory a owl:Class ;
  owl:disjointUnionOf ( ea:ProductOutput ea:PerformanceOutput ) ;
  rdfs:comment "Performance formats are further classified into products and performances." .

ea:ProductOutput a owl:Class ; rdfs:subClassOf ea:PerformanceOutputCategory ;
  rdfs:comment "A painting, portfolio, paper, or exhibition." .
ea:PerformanceOutput a owl:Class ; rdfs:subClassOf ea:PerformanceOutputCategory ;
  rdfs:comment "A speech, athletic skill, musical recital, or reading." .

ea:PerformanceAssessment a owl:Class ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( ea:EducationalAssessment
      [ a owl:Restriction ; owl:onProperty ea:hasOutputFormat ; owl:someValuesFrom ea:PerformanceOutputCategory ] ) ] ;
  skos:altLabel "performance-based assessment" ;
  rdfs:comment "Similar to summative assessment in that it focuses on achievement; a well-defined task is identified and students create, produce, or do something, often involving real-world application. Distinguished from ea:AuthenticAssessment though closely related in the corpus; distinguished from ea:PerformanceTest which denotes the hands-on modality rather than the product/performance output." .

#################################################################
## COMPETENCY-BASED LEARNING
#################################################################

ea:CompetencyBasedLearning a owl:Class ;
  skos:altLabel "proficiency-based learning", "mastery-based learning", "outcome-based learning",
                "performance-based learning", "standards-based education" ;
  rdfs:comment "Systems of instruction, assessment, grading, and reporting based on students demonstrating learning. NOTE: the synonym 'performance-based' here denotes an instructional system, distinct from ea:PerformanceAssessment which is a kind of educational assessment." .

#################################################################
## PORTFOLIO
#################################################################

ea:Portfolio a owl:Class ; rdfs:subClassOf ea:EducationalAssessment ;
  skos:altLabel "student portfolio" ;
  rdfs:comment "A compilation of academic work and other evidence assembled to evaluate coursework quality, learning progress, and achievement." .

ea:DigitalPortfolio a owl:Class ; rdfs:subClassOf ea:Portfolio ;
  skos:altLabel "e-portfolio", "digital portfolio" .

ea:CapstonePortfolio a owl:Class ; rdfs:subClassOf ea:Portfolio ;
  rdfs:comment "Features student work completed as part of long-term, culminating projects." .

#################################################################
## ASSESSMENT ITEMS
#################################################################

ea:AssessmentItem a owl:Class ;
  skos:altLabel "item" ;
  rdfs:comment "The more general term 'item' is preferred to 'question' since many items are not phrased as questions (e.g., incomplete statements, analogies, equations)." .

ea:ObjectiveItem a owl:Class ; rdfs:subClassOf ea:AssessmentItem .
ea:SubjectiveItem a owl:Class ; rdfs:subClassOf ea:AssessmentItem .
ea:ObjectiveItem owl:disjointWith ea:SubjectiveItem .

ea:TrueFalseItem a owl:Class ; rdfs:subClassOf ea:ObjectiveItem .
ea:MultipleChoiceItem a owl:Class ; rdfs:subClassOf ea:ObjectiveItem ;
  skos:altLabel "MCQ", "multiple choice question", "objective response" .
ea:MultipleResponseItem a owl:Class ; rdfs:subClassOf ea:ObjectiveItem ;
  rdfs:comment "More than one answer may be keyed as correct, unlike MultipleChoiceItem." .
ea:MatchingItem a owl:Class ; rdfs:subClassOf ea:ObjectiveItem .

ea:ObjectiveItem owl:disjointUnionOf ( ea:TrueFalseItem ea:MultipleChoiceItem ea:MultipleResponseItem ea:MatchingItem ) .

ea:ExtendedResponseItem a owl:Class ; rdfs:subClassOf ea:SubjectiveItem .
ea:EssayItem a owl:Class ; rdfs:subClassOf ea:SubjectiveItem ;
  skos:altLabel "essay question", "free response question", "FRQ" .

ea:SubjectiveItem owl:disjointUnionOf ( ea:ExtendedResponseItem ea:EssayItem ) .

ea:FillInTheBlankItem a owl:Class ; rdfs:subClassOf ea:AssessmentItem .
ea:ShortAnswerItem a owl:Class ; rdfs:subClassOf ea:AssessmentItem .

ea:TrueFalseResponseFamily a owl:Class ; rdfs:subClassOf ea:MultipleChoiceItem ;
  rdfs:comment "Requires the test taker to choose all answers that are appropriate." .
ea:OneBestAnswerFamily a owl:Class ; rdfs:subClassOf ea:MultipleChoiceItem ;
  rdfs:comment "Requires the test taker to answer only one from a list of answers." .

[] a owl:AllDisjointClasses ; owl:members ( ea:TrueFalseResponseFamily ea:OneBestAnswerFamily ) .

ea:MultipleChoiceItem rdfs:comment "TENSION: elsewhere, 'True/False' is listed as a sibling objective-item type coordinate with (not subsumed by) multiple-choice ('Objective question types include true/false, multiple-choice, multiple-response, and matching questions'). However another passage states 'there are two families of multiple-choice questions': the True/False family and the One-Best-Answer family, making true/false a subclass of multiple-choice. Both claims are modeled (ea:TrueFalseItem as sibling of ea:MultipleChoiceItem, and ea:TrueFalseResponseFamily as subclass of ea:MultipleChoiceItem)." .

ea:AnswerOption a owl:Class .
ea:Key a owl:Class ; rdfs:subClassOf ea:AnswerOption .
ea:Distractor a owl:Class ; rdfs:subClassOf ea:AnswerOption .
ea:Key owl:disjointWith ea:Distractor .

ea:hasOption a owl:ObjectProperty ; rdfs:domain ea:AssessmentItem ; rdfs:range ea:AnswerOption .
ea:hasKey a owl:ObjectProperty ; rdfs:subPropertyOf ea:hasOption ;
  rdfs:domain ea:AssessmentItem ; rdfs:range ea:Key .
ea:hasDistractor a owl:ObjectProperty ; rdfs:subPropertyOf ea:hasOption ;
  rdfs:domain ea:AssessmentItem ; rdfs:range ea:Distractor .

ea:MultipleChoiceItem rdfs:subClassOf
  [ a owl:Restriction ; owl:onProperty ea:hasKey ; owl:onClass ea:Key ; owl:qualifiedCardinality "1"^^xsd:nonNegativeInteger ] ;
  rdfs:comment "Only one answer may be keyed as correct." .

ea:MultipleResponseItem rdfs:subClassOf
  [ a owl:Restriction ; owl:onProperty ea:hasKey ; owl:onClass ea:Key ; owl:minQualifiedCardinality "2"^^xsd:nonNegativeInteger ] .

ea:hasStemText a owl:DatatypeProperty, owl:FunctionalProperty ;
  rdfs:domain ea:AssessmentItem ; rdfs:range xsd:string ;
  rdfs:comment "The stem is the opening: a problem, question, or incomplete statement." .

#################################################################
## TESTS COMPOSED OF ITEMS
#################################################################

ea:hasItem a owl:ObjectProperty ; rdfs:domain ea:Test ; rdfs:range ea:AssessmentItem .
ea:isItemOf a owl:ObjectProperty ; owl:inverseOf ea:hasItem ;
  rdfs:domain ea:AssessmentItem ; rdfs:range ea:Test .

ea:hasItemCount a owl:DatatypeProperty ; rdfs:domain ea:Test ; rdfs:range xsd:integer .

ea:MultipleChoiceTest a owl:Class ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( ea:Test
      [ a owl:Restriction ; owl:onProperty ea:hasItem ; owl:someValuesFrom ea:MultipleChoiceItem ] ) ] .

ea:EssayTest a owl:Class ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf ( ea:Test
      [ a owl:Restriction ; owl:onProperty ea:hasItem ; owl:someValuesFrom ea:EssayItem ] ) ] .

ea:TrueFalseTest a owl:Class ; rdfs:subClassOf ea:Test .
ea:FillInTheBlankTest a owl:Class ; rdfs:subClassOf ea:Test .
ea:ShortAnswerTest a owl:Class ; rdfs:subClassOf ea:Test .

#################################################################
## VALIDITY
#################################################################

ea:hasValidity a owl:ObjectProperty ; rdfs:domain ea:EducationalAssessment ; rdfs:range ea:Validity .

ea:Validity a owl:Class ;
  rdfs:comment "The degree to which an assessment measures what it is intended to measure." .

ea:ContentValidity a owl:Class ; rdfs:subClassOf ea:Validity ; skos:altLabel "logical validity" .
ea:CriterionValidity a owl:Class ; rdfs:subClassOf ea:Validity .
ea:ConstructValidity a owl:Class ; rdfs:subClassOf ea:Validity .
ea:ConsequentialValidity a owl:Class ; rdfs:subClassOf ea:Validity .
ea:FaceValidity a owl:Class ; rdfs:subClassOf ea:Validity .

ea:Validity owl:disjointUnionOf ( ea:ContentValidity ea:CriterionValidity ea:ConstructValidity
                                   ea:ConsequentialValidity ea:FaceValidity ) ;
  rdfs:comment "Validity is gauged through examination of evidence in these coordinate categories (content, criterion, construct, consequential, face)." .

ea:ConstructValidity rdfs:comment "TENSION: construct validity is also stated to 'subsume all other types of validity' (making content/criterion/face validity subclasses of it), which conflicts with the coordinate, pairwise-disjoint partition of ea:Validity asserted above. Both claims are modeled: the disjoint partition, and the subsumption axioms below." .

ea:ContentValidity rdfs:subClassOf ea:ConstructValidity .
ea:CriterionValidity rdfs:subClassOf ea:ConstructValidity .
ea:FaceValidity rdfs:subClassOf ea:ConstructValidity .

ea:ConcurrentValidity a owl:Class ; rdfs:subClassOf ea:CriterionValidity ;
  rdfs:comment "Test data and criterion data collected at the same time." .
ea:PredictiveValidity a owl:Class ; rdfs:subClassOf ea:CriterionValidity ;
  rdfs:comment "Test data collected first in order to predict criterion data collected later." .
ea:CriterionValidity owl:disjointUnionOf ( ea:ConcurrentValidity ea:PredictiveValidity ) .

ea:ConvergentValidity a owl:Class ; rdfs:subClassOf ea:ConstructValidity .
ea:DiscriminantValidity a owl:Class ; rdfs:subClassOf ea:ConstructValidity ;
  skos:altLabel "divergent validity" .
ea:ConstructValidity owl:disjointUnionOf ( ea:ConvergentValidity ea:DiscriminantValidity ) ;
  rdfs:comment "Convergent and discriminant validity are the two subtypes of validity that make up construct validity." .

#################################################################
## RELIABILITY
#################################################################

ea:hasReliability a owl:ObjectProperty ; rdfs:domain ea:EducationalAssessment ; rdfs:range ea:Reliability .
ea:hasReliabilityCoefficient a owl:DatatypeProperty ; rdfs:domain ea:Reliability ; rdfs:range xsd:decimal .

ea:Reliability a owl:Class ;
  rdfs:comment "Consistency of an assessment: it consistently achieves the same results with the same/similar cohort." .

ea:StudentRelatedReliability a owl:Class ; rdfs:subClassOf ea:Reliability .
ea:RaterRelatedReliability a owl:Class ; rdfs:subClassOf ea:Reliability .
ea:TestAdministrationRelatedReliability a owl:Class ; rdfs:subClassOf ea:Reliability .
ea:TestRelatedReliability a owl:Class ; rdfs:subClassOf ea:Reliability .

ea:Reliability owl:disjointUnionOf ( ea:StudentRelatedReliability ea:RaterRelatedReliability
                                      ea:TestAdministrationRelatedReliability ea:TestRelatedReliability ) ;
  rdfs:comment "There are four types of reliability, classified by source of error: student-related, rater-related, test administration-related, test-related." .

ea:InterRaterReliability a owl:Class ; rdfs:subClassOf ea:Reliability .
ea:TestRetestReliability a owl:Class ; rdfs:subClassOf ea:Reliability ;
  skos:altLabel "repeatability" .
ea:IntraRaterReliability a owl:Class ; rdfs:subClassOf ea:TestRetestReliability .
ea:InterMethodReliability a owl:Class ; rdfs:subClassOf ea:Reliability ;
  skos:altLabel "parallel-forms reliability" .
ea:InternalConsistencyReliability a owl:Class ; rdfs:subClassOf ea:Reliability .
ea:SplitHalfMethod a owl:Class ; rdfs:subClassOf ea:InternalConsistencyReliability ;
  rdfs:comment "Treats the two halves of a measure as alternate forms; result stepped up via the Spearman-Brown prediction formula." .

[] a owl:AllDisjointClasses ;
   owl:members ( ea:InterRaterReliability ea:TestRetestReliability
                 ea:InterMethodReliability ea:InternalConsistencyReliability ) ;
   rdfs:comment "Second, independent classification axis: 'general classes of reliability estimates', distinct from the source-of-error axis above." .

ea:InterRaterAgreementStatistic a owl:Class .
ea:JointProbabilityOfAgreement a owl:Class ; rdfs:subClassOf ea:InterRaterAgreementStatistic .
ea:CohensKappa a owl:Class ; rdfs:subClassOf ea:InterRaterAgreementStatistic .
ea:ScottsPi a owl:Class ; rdfs:subClassOf ea:InterRaterAgreementStatistic .
ea:FleissKappa a owl:Class ; rdfs:subClassOf ea:InterRaterAgreementStatistic .
ea:IntraclassCorrelation a owl:Class ; rdfs:subClassOf ea:InterRaterAgreementStatistic .
ea:KrippendorffsAlpha a owl:Class ; rdfs:subClassOf ea:InterRaterAgreementStatistic .
ea:ConcordanceCorrelationCoefficient a owl:Class ; rdfs:subClassOf ea:InterRaterAgreementStatistic .

#################################################################
## RUBRIC & GRADING
#################################################################

ea:hasRubric a owl:ObjectProperty ; rdfs:domain ea:EducationalAssessment ; rdfs:range ea:Rubric .

ea:Rubric a owl:Class ;
  skos:altLabel "scoring guide" ;
  rdfs:comment "A scoring guide used to evaluate the quality of students' constructed responses." .

ea:HolisticRubric a owl:Class ; rdfs:subClassOf ea:Rubric .
ea:AnalyticRubric a owl:Class ; rdfs:subClassOf ea:Rubric .
ea:DevelopmentalRubric a owl:Class ; rdfs:subClassOf ea:Rubric .

ea:Rubric owl:disjointUnionOf ( ea:HolisticRubric ea:AnalyticRubric ea:DevelopmentalRubric ) ;
  rdfs:comment "Rubrics can be classified as holistic, analytic, or developmental (coordinate, pairwise disjoint)." .

ea:DevelopmentalRubric rdfs:subClassOf ea:AnalyticRubric ;
  rdfs:comment "TENSION: corpus also states developmental rubrics are 'a subset of analytical rubrics' (subordinate), conflicting with the coordinate three-way disjoint partition above. Both claims modeled." .

ea:GradingApproach a owl:Class .
ea:HolisticGrading a owl:Class ; rdfs:subClassOf ea:GradingApproach ;
  skos:altLabel "holistic scoring", "nonreductionist grading" .
ea:AnalyticGrading a owl:Class ; rdfs:subClassOf ea:GradingApproach ;
  skos:altLabel "analytic scoring" .
ea:GradingApproach owl:disjointUnionOf ( ea:HolisticGrading ea:AnalyticGrading ) .

ea:TraitInformedScoring a owl:Class ; rdfs:subClassOf ea:HolisticGrading ;
  rdfs:comment "Comes close to analytic scoring methods (scoring traits independently) but 'remains holistic at heart', asking raters to consider all traits before a single final score." .

#################################################################
## DATATYPE PROPERTIES (cut scores, points)
#################################################################

ea:hasCutScore a owl:DatatypeProperty ; rdfs:domain ea:EducationalAssessment ; rdfs:range xsd:decimal .
ea:hasPointValue a owl:DatatypeProperty ; rdfs:domain ea:Test ; rdfs:range xsd:decimal .

#################################################################
## LEARNING OUTCOME
#################################################################

ea:hasLearningOutcome a owl:ObjectProperty ; rdfs:domain ea:EducationalAssessment ; rdfs:range ea:LearningOutcome .

ea:LearningOutcome a owl:Class ;
  rdfs:comment "Statements about what students should be able to do by the end of a teaching session." .

ea:IntendedLearningOutcome a owl:Class ; rdfs:subClassOf ea:LearningOutcome ;
  rdfs:comment "Equated with 'aims'." .
ea:MeasuredLearningOutcome a owl:Class ; rdfs:subClassOf ea:LearningOutcome ;
  rdfs:comment "Equated with 'objectives'." .
ea:UnintendedLearningOutcome a owl:Class ; rdfs:subClassOf ea:LearningOutcome ;
  rdfs:comment "Beneficial outcomes neither planned nor sought but observed." .

ea:LearningOutcome owl:disjointUnionOf ( ea:IntendedLearningOutcome ea:MeasuredLearningOutcome ea:UnintendedLearningOutcome ) .

ea:LearningOutcomeTaxonomy a owl:Class .
ea:BloomsTaxonomy a owl:Class ; rdfs:subClassOf ea:LearningOutcomeTaxonomy .
ea:StructureOfObservedLearningOutcome a owl:Class ; rdfs:subClassOf ea:LearningOutcomeTaxonomy ; skos:altLabel "SOLO" .
ea:DikwPyramid a owl:Class ; rdfs:subClassOf ea:LearningOutcomeTaxonomy ; skos:altLabel "DIKW pyramid" .
ea:ModelOfHierarchicalComplexity a owl:Class ; rdfs:subClassOf ea:LearningOutcomeTaxonomy .

ea:LearningOutcomeTaxonomy owl:disjointUnionOf ( ea:BloomsTaxonomy ea:StructureOfObservedLearningOutcome
                                                   ea:DikwPyramid ea:ModelOfHierarchicalComplexity ) .

ea:ConstructiveAlignment a owl:Class ;
  rdfs:comment "Principle for devising teaching/learning activities and assessment tasks that directly address intended learning outcomes." .

#################################################################
## VALUE-ADDED / GROWTH / MEASUREMENT ERROR / SCORE INFLATION
#################################################################

ea:ValueAddedMeasure a owl:Class ; skos:altLabel "growth measure" ;
  rdfs:comment "Estimates how much of a positive or negative effect individual teachers have on student learning, using statistical algorithms and standardized-test results." .

ea:StudentGrowthMeasure a owl:Class ;
  rdfs:comment "A related but distinct method of using student test scores to quantify academic achievement and growth." .

ea:MeasurementError a owl:Class ;
  rdfs:comment "The difference between what a test score indicates and a student's actual knowledge/abilities, or errors introduced in data collection/reporting." .

ea:ScoreInflation a owl:Class ;
  rdfs:comment "Scores increase without genuine improvement in learning." .

ea:ProficiencyLevel a owl:Class ;
  rdfs:comment "A level of achievement defined by standards, scales, and cut-off scores." .

#################################################################
## FEEDBACK
#################################################################

ea:Feedback a owl:Class .
ea:CorrectiveFeedback a owl:Class ; rdfs:subClassOf ea:Feedback ;
  rdfs:comment "Nonevaluative, supportive, timely, specific feedback on understanding or performance." .
ea:Recast a owl:Class ; rdfs:subClassOf ea:CorrectiveFeedback ;
  rdfs:comment "A subtle correction of a spoken error, typical of motherese." .

#################################################################
## TRANSFER OF LEARNING
#################################################################

ea:TransferOfLearning a owl:Class ;
  rdfs:comment "Application of skill, knowledge, or understanding to resolve a novel problem or situation." .

ea:NearTransfer a owl:Class ; rdfs:subClassOf ea:TransferOfLearning ;
  rdfs:comment "Application of skill to a novel problem in a similar context." .
ea:FarTransfer a owl:Class ; rdfs:subClassOf ea:TransferOfLearning ;
  rdfs:comment "Application of skill to a novel problem in a different context." .
ea:TransferOfLearning owl:disjointUnionOf ( ea:NearTransfer ea:FarTransfer ) .

ea:PositiveTransfer a owl:Class ; rdfs:subClassOf ea:TransferOfLearning .
ea:NegativeTransfer a owl:Class ; rdfs:subClassOf ea:TransferOfLearning .
[] a owl:AllDisjointClasses ; owl:members ( ea:PositiveTransfer ea:NegativeTransfer ) ;
  rdfs:comment "Second, independent classification axis (by valence) distinct from the near/far axis (by context similarity)." .

#################################################################
## LEARNING FORMALITY (context, not assessment)
#################################################################

ea:Learning a owl:Class .
ea:FormalLearning a owl:Class ; rdfs:subClassOf ea:Learning .
ea:NonFormalLearning a owl:Class ; rdfs:subClassOf ea:Learning .
ea:InformalLearning a owl:Class ; rdfs:subClassOf ea:Learning .
ea:Learning owl:disjointUnionOf ( ea:FormalLearning ea:NonFormalLearning ea:InformalLearning ) .
